const literals=Object.keys(D).filter(k=>k.length>2).sort((a,b)=>b.length-a.length);
const phrases=new RegExp(literals.map(escape).join('|'),'g');
function t(value){
 const s=String(value||''),n=s.trim();if(!n)return s;
 const guarded=window.DEEN_CONTENT_LOCALE?.translateText(n,'en');if(guarded&&guarded!==n)return s.replace(n,guarded);
 if(D[n])return s.replace(n,D[n]);
 let m;
 if((m=n.match(/^(\d+) kavram henüz dengeli değil\. Review planında bunlar daha görünür olacak\.$/)))return m[1]+(m[1]==='1'?' concept still needs':' concepts still need')+' more practice. Your review plan will prioritize '+(m[1]==='1'?'it.':'them.');
 // Word-frequency counters in Quran vocabulary use complete English units.
 if((m=n.match(/^(\d+) tekrar$/)))return m[1]+(m[1]==='1'?' occurrence':' occurrences');
 if((m=n.match(/^(\d+) sure$/)))return m[1]+(m[1]==='1'?' surah':' surahs');
 // Quran hub counters and Turkish-short-month dates: match whole labels, not fragments.
 if((m=n.match(/^(\d{1,2})\s+(Oca|Şub|Mar|Nis|May|Haz|Tem|Ağu|Eyl|Eki|Kas|Ara)\.?$/))){
  const months={Oca:'Jan',Şub:'Feb',Mar:'Mar',Nis:'Apr',May:'May',Haz:'Jun',Tem:'Jul',Ağu:'Aug',Eyl:'Sep',Eki:'Oct',Kas:'Nov',Ara:'Dec'};
  return m[1]+' '+months[m[2]];
 }
 if((m=n.match(/^(\d+)\s+zayıf ayet$/)))return m[1]+' weaker ayahs';
 if((m=n.match(/^(\d+)\s+tekrar bugün$/)))return m[1]+' reviews due today';
 if((m=n.match(/^(\d+)\/90 ayet$/)))return m[1]+'/90 ayahs';
 if((m=n.match(/^(\d+)\/3 görev$/)))return m[1]+'/3 tasks';
 if((m=n.match(/^(\d+)\s+sure\s*·\s*(\d+)\s+ayet$/i)))return m[1]+' surahs · '+m[2]+' ayahs';
 if((m=n.match(/^Ustalık\s*%(\d+)$/)))return 'Mastery '+m[1]+'%';
 if((m=n.match(/^%(\d+)\s+hafıza$/)))return m[1]+'% memory strength';
 if((m=n.match(/^(\d+)\s+sn$/)))return s.replace(n,m[1]+' sec');
 if(m=n.match(/^(?:Ayet|Verse) (\d+) sesini dinle$/))return 'Listen to Verse '+m[1];
 if(m=n.match(/^(.+) kelimesini boşluğa yerleştir$/))return 'Place '+t(m[1])+' in the blank';
 if(m=n.match(/^(Kavram|Eş):\s*(.+)$/))return (m[1]==='Kavram'?'Concept: ':'Match: ')+t(m[2]);
 if(m=n.match(/^İfade\s+(\d+):\s*(.+)$/))return 'Statement '+m[1]+': '+t(m[2]);
 if(m=n.match(/^(\d+) soruda hata tekrar ediyor\. Akıllı tekrar bu sinyalleri önceliklendirecek\.$/))return 'Mistakes recur in '+m[1]+' questions. Smart review will prioritize these signals.';
 if(m=n.match(/^Doğru cevap:\s*([\s\S]+)$/))return 'Correct answer: '+t(m[1]);
 if(m=n.match(/^(Kısaca|Özet):\s*([\s\S]+)$/))return (m[1]==='Kısaca'?'In brief: ':'Summary: ')+t(m[2]);
 if(m=n.match(/^(\d+)\. KISIM\s*·\s*(\d+)\. ÜNİTE$/))return 'SECTION '+m[1]+' · UNIT '+m[2];
 if(m=n.match(/^KISIM (\d+) TAMAMLANDI · USTALIK$/))return 'SECTION '+m[1]+' COMPLETED · MASTERY';
 const parts=n.split(/(\s*[·—→]\s*)/);if(parts.length>1)return parts.map((p,i)=>i%2?p:t(p)).join('');
 let out=n.replace(phrases,(k,at,whole)=>{const before=whole[at-1]||'',after=whole[at+k.length]||'';return /[\p{L}]/u.test(before+after)?k:D[k]});
 if(/REQUIRES_EXPERT_VERIFICATION|Diyanet|Quran Path/.test(out))out=out.replace(/Kur['’]an/g,'Quran').replace(/Cilt\s*(\d+)/g,'Vol. $1').replace(/\bs\.(\d+)/g,'p. $1').replace(/\bve\b/g,'and').replace(/\bbölümü\b/g,'chapter').replace(/Buhârî/g,'Al-Bukhari').replace(/Müslim/g,'Muslim').replace(/Îmân/g,'Faith').replace(/Maûn/g,"Al-Ma'un");
 return s.replace(n,out);
}
